from pathlib import Path
import subprocess
rec={}; name=None
for line in Path('sequences.fasta').read_text().splitlines():
    if line.startswith('>'): name=line[1:].strip(); rec[name]=''
    else: rec[name]+=line.strip().lower()
s=rec['input']; boundary=215
up=s[:boundary]; down=s[boundary:]
def rc(x): return x.translate(str.maketrans('acgt','tgca'))[::-1]
def tm(x):
    return float(subprocess.check_output(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',x], text=True).strip())
rows=[]
for lf in range(15,37):
    f=down[:lf]; tf=tm(f)
    for lr in range(15,37):
        r=rc(up[-lr:]); tr=tm(r)
        if 58<=tf<=72 and 58<=tr<=72 and abs(tf-tr)<=5:
            rows.append((abs(tf-tr),-(tf+tr),lf,lr,f,r,tf,tr))
for row in sorted(rows)[:20]:
    diff,_,lf,lr,f,r,tf,tr=row
    print(f'lf={lf:2d} lr={lr:2d} Tm={tf:6.2f}/{tr:6.2f} diff={tf-tr:+.2f}\nFanneal={f}\nRanneal={r}')
print('total candidates',len(rows))
